<script setup>import {router} from '@inertiajs/vue3'; import AppLayout from '../../../Layouts/AppLayout.vue'; import PaginationLinks from '../../../components/ui/PaginationLinks.vue'; const props=defineProps({report:String,entries:Object,accounts:Array,account:Object,lines:Array,opening:[String,Number],from:String,to:String}); const go=(extra={})=>router.get(window.location.pathname,{date_from:props.from,date_to:props.to,...extra});</script>
<template><AppLayout :title="report==='journal'?'Libro diario':report==='ledger'?'Libro mayor':'Balance de comprobación'" eyebrow="Reportes contables"><div class="card mb-4 flex flex-wrap gap-3 p-4"><input :value="from" type="date" class="control m-0 w-auto" @change="go({date_from:$event.target.value})"><input :value="to" type="date" class="control m-0 w-auto" @change="go({date_to:$event.target.value})"><select v-if="report==='ledger'" class="control m-0 min-w-60" :value="account?.id||''" @change="go({account:$event.target.value})"><option value="">Seleccionar cuenta</option><option v-for="row in accounts" :key="row.id" :value="row.id">{{row.code}} · {{row.name}}</option></select></div><section class="card overflow-hidden"><div v-if="report==='journal'" class="divide-y"><div v-for="entry in entries.data" :key="entry.id" class="p-4"><p class="font-semibold">{{entry.number}} · {{entry.concept}}</p><p class="text-xs text-slate-400">{{entry.date}}</p><div class="mt-2 text-xs" v-for="line in entry.lines" :key="line.id">{{line.account.code}} · Debe {{line.debit}} · Haber {{line.credit}}</div></div><PaginationLinks :links="entries.links"/></div><div v-else-if="report==='ledger'" class="p-5"><p v-if="account" class="mb-4 font-semibold">{{account.code}} · {{account.name}} · Saldo inicial {{opening}}</p><div v-for="line in lines" :key="line.id" class="grid grid-cols-4 border-b py-3 text-xs"><span>{{line.journal_entry.date}}</span><span>{{line.journal_entry.number}}</span><span>Debe {{line.debit}}</span><span>Haber {{line.credit}}</span></div><p v-if="!account" class="empty-state">Selecciona una cuenta.</p></div><div v-else class="table-wrap"><table class="w-full"><thead><tr><th class="table-cell">Cuenta</th><th class="table-cell text-right">Debe</th><th class="table-cell text-right">Haber</th></tr></thead><tbody><tr v-for="row in accounts" :key="row.id"><td class="table-cell">{{row.code}} · {{row.name}}</td><td class="table-cell text-right">{{row.debit||0}}</td><td class="table-cell text-right">{{row.credit||0}}</td></tr></tbody></table></div></section></AppLayout></template>
